everity":"atencao","monthDay":"04-23","name":"São Jorge (Feriado Estadual)","dayType":"FERIADO"},{"id":"rg-feriado-3","kind":"feriado-local-esperado","enabled":true,"severity":"atencao","monthDay":"05-10","name":"Aniversário da cidade (Feriado Letivo)","dayType":"FL"}],"document":{"headerLines":["PREFEITURA MUNICIPAL DE ITAPERUNA","SECRETARIA MUNICIPAL DE EDUCAÇÃO","SUPERVISÃO DE ENSINO"],"showHolidays":true,"showPeriods":true,"showGroupSummaries":true,"showCouncils":true,"showAnnualTotal":true},"audit":[{"at":"2026-09-23T12:00:00.000Z","actorId":"sup-ref","actorName":"Supervisão de Ensino","action":"criado","detail":"Calendário 2027 — Ensino Regular."}]}}}'::jsonb; s1 jsonb; s2 jsonb; h jsonb; r jsonb; v jsonb; ok boolean;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', sv, 'role','authenticated')::text, true);
  PERFORM set_config('role', 'authenticated', true);
  s1 := public.save_network_calendar('cal-rede-2027-regular', NULL, pl);
  IF (s1->>'version')::int <> 1 THEN RAISE EXCEPTION 'v1 esperada: %', s1; END IF;
  h := public.homologate_network_calendar((s1->>'versionId')::uuid, NULL, 'ato teste', NULL);
  -- alteração: nova versão sobre a base, histórico preservado
  s2 := public.save_network_calendar('cal-rede-2027-regular', (s1->>'versionId')::uuid, jsonb_set(pl, '{title}', '"Regular alterado"'));
  IF (s2->>'version')::int <> 2 THEN RAISE EXCEPTION 'v2 esperada: %', s2; END IF;
  -- conflito: base antiga
  ok := false;
  BEGIN PERFORM public.save_network_calendar('cal-rede-2027-regular', (s1->>'versionId')::uuid, pl);
  EXCEPTION WHEN others THEN IF SQLERRM LIKE '%base-superseded%' THEN ok := true; ELSE RAISE; END IF; END;
  IF NOT ok THEN RAISE EXCEPTION 'conflito não detectado'; END IF;
  r := public.calendar_network_sources_at(NULL);
  IF r->>'audience' <> 'construcao' OR jsonb_array_length(r->'sources') <> 1 THEN RAISE EXCEPTION 'fontes sv: %', r; END IF;
  -- conta comum: só a v1 homologada
  PERFORM set_config('request.jwt.claims', json_build_object('sub', other, 'role','authenticated')::text, true);
  r := public.calendar_list_at(clock_timestamp());
  IF r->>'audience' <> 'homologados' THEN RAISE EXCEPTION 'comum audience %', r->>'audience'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(r->'versions') x) <> 1 OR (r->'versions'->0->>'version')::int <> 1 THEN RAISE EXCEPTION 'comum deveria ver só v1: %', r->'versions'; END IF;
  r := public.calendar_presentation_at((s1->>'versionId')::uuid, (r->'versions'->0->>'validFrom')::date, clock_timestamp());
  IF r->>'state' <> 'lido' OR r->'snapshot'->'presentation'->'editorCalendar'->>'id' <> 'cal-rede-2027-regular' THEN RAISE EXCEPTION 'apresentação comum: %', left(r::text, 300); END IF;
  ok := false;
  BEGIN PERFORM public.save_network_calendar('x', NULL, pl);
  EXCEPTION WHEN others THEN ok := true; END;
  IF NOT ok THEN RAISE EXCEPTION 'comum salvou'; END IF;
  RAISE EXCEPTION 'b4610-cycle-ok';
END $$;
